export class GenerateAuthenticationTokenRequest {
  constructor(userId: string, timeToLive?: number) {
    this.userId = userId;
    this.timeToLive = timeToLive;
  }

  userId: string;

  timeToLive?: number;
}

export default GenerateAuthenticationTokenRequest;

export class GeneratedAuthenticationTokenResponse {
  token!: string;
}

export default GeneratedAuthenticationTokenResponse;

export enum AuthenticatorAttachment {
  ANY = "any",

  /**
   * A platform authenticator is attached using a client device-specific transport, called platform attachment, and is usually not removable from the client device.
   */
  PLATFORM = "platform",

  /**
   * A roaming authenticator is attached using cross-platform transports, called cross-platform attachment. Authenticators of this class are removable from, and can "roam" between, client devices.
   */
  CROSS_PLATFORM = "cross-platform",
}

export default AuthenticatorAttachment;

export enum Attestation {
  /**
   * A value of "none" indicates that the server does not care about attestation.
   */
  NONE = "none",

  /**
   * A value of "direct" means that the server wishes to receive the attestation data from the authenticator.
   */
  DIRECT = "direct",

  /**
   * A value of "indirect" means that the server will allow for anonymized attestation data.
   */
  INDIRECT = "indirect",
}

export default Attestation;

export class RegisterTokenResponse {
  token!: string;
}

export default RegisterTokenResponse;

export class ListResponse<T> {
  values: T[] = [];
}

export default ListResponse;

export class ProblemDetails {
  type?: string;

  title?: string;

  status?: number;

  errorCode?: string;

  instance?: string;

  detail?: string;
}

export default ProblemDetails;

export class DeleteUserRequest {
  constructor(userId: string) {
    this.userId = userId;
  }

  userId!: string;
}

export default DeleteUserRequest;

export class VerifyTokenRequest {
  constructor(token: string) {
    this.token = token;
  }

  token: string;

  rpid?: string;

  serverName?: string;

  origin?: string;
}

export default VerifyTokenRequest;

import Converters from "../Converters";

export class CredentialDescriptor {
  public id: string = "";

  public getId(): Uint8Array {
    return Converters.base64UrlToUint8Array(this.id);
  }
}

export default CredentialDescriptor;

import Converters from "../Converters";

export class DeleteCredentialRequest {
  constructor(credentialId: Uint8Array) {
    this.credentialId = Converters.uint8ArrayToBase64Url(credentialId);
  }

  credentialId: string;
}

export default DeleteCredentialRequest;

export class AliasPointer {
  public userId?: string;

  public alias?: string;

  public plaintext?: string;
}

export default AliasPointer;

export class SendMagicLinkRequest {
  constructor(
    emailAddress: string,
    urlTemplate: string,
    userId: string,
    timeToLive?: number,
  ) {
    this.emailAddress = emailAddress;
    this.urlTemplate = urlTemplate;
    this.userId = userId;
    this.timeToLive = timeToLive;
  }

  emailAddress: string;

  urlTemplate: string;

  userId: string;

  timeToLive?: number;
}

export default SendMagicLinkRequest;

import Converters from "../Converters";

export class VerifiedUser {
  userId!: string;

  credentialId!: string;

  public getCredentialId(): Uint8Array {
    return Converters.base64UrlToUint8Array(this.credentialId);
  }

  success: boolean = false;

  timestamp?: Date;

  rpid?: string;

  origin?: string;

  device?: string;

  country?: string;

  nickname?: string;

  expiresAt?: Date;

  tokenId?: string;

  type?: string;
}

export default VerifiedUser;

export class AuditLog {
  public timestamp?: Date;

  public level?: string;

  public message?: string;

  public details?: string;
}

export default AuditLog;

import Converters from "../Converters";
import CredentialDescriptor from "./CredentialDescriptor";

export class Credential {
  public descriptor!: CredentialDescriptor;

  public publicKey!: string;

  public getPublicKey(): Uint8Array {
    return Converters.base64UrlToUint8Array(this.publicKey);
  }

  public userHandle!: string;

  public getUserHandle(): Uint8Array {
    return Converters.base64UrlToUint8Array(this.userHandle);
  }

  public signatureCounter?: number;

  public attestationFmt?: string;

  public createdAt?: Date;

  public aaGuid?: string;

  public lastUsedAt?: Date;

  public rpid?: string;

  public origin?: string;

  public country?: string;

  public device?: string;

  public nickname?: string;

  public userId?: string;
}

export default Credential;

import ProblemDetails from "../models/ProblemDetails";

export class ApiException extends Error {
  private _details: ProblemDetails;

  constructor(details: ProblemDetails) {
    super();
    this._details = details;
  }

  public get details(): ProblemDetails {
    return this._details;
  }
}

export default ApiException;

export class SetAliasRequest {
  constructor(userId: string, aliases: string[] = [], hashing: boolean = true) {
    this.userId = userId;
    this.aliases = aliases;
    this.hashing = hashing;
  }

  public userId: string;

  /**
   * Aliases to add to the user. Existing aliases not included in this request will be removed.
   */
  public aliases: string[] = [];

  /**
   * Whether to hash the aliases before storing them.
   */
  public hashing: boolean = true;
}

export default SetAliasRequest;
